"""Interval-based target and port selection, without expanding large networks."""
import ipaddress
import re


def merge(items):
    result = []
    for lo, hi in sorted(items):
        if hi < lo:
            continue
        if result and result[-1][1] + 1 >= lo:
            result[-1] = (result[-1][0], max(result[-1][1], hi))
        else:
            result.append((lo, hi))
    return result


def subtract(items, exclusions):
    items = merge(items)
    for lo, hi in merge(exclusions):
        result = []
        for a, b in items:
            if hi < a or lo > b:
                result.append((a, b))
            else:
                if a < lo:
                    result.append((a, lo - 1))
                if b > hi:
                    result.append((hi + 1, b))
        items = result
    return items


def address(s):
    if ':' in s:
        return ipaddress.IPv6Address(s)
    parts = s.split('.')
    if len(parts) != 4 or not all(p.isdigit() and int(p) <= 255 for p in parts):
        raise ValueError(s)
    return ipaddress.IPv4Address(bytes(int(p) for p in parts))


def ip_range(s):
    if '-' in s:
        a, b = s.split('-', 1)
        a, b = address(a.strip()), address(b.strip())
        if a.version != b.version:
            raise ValueError(s)
        return a.version, int(a), int(b)
    if '/' in s:
        a, bits = s.split('/', 1)
        a = address(a)
        width = 32 if a.version == 4 else 128
        if not bits.isdigit() or not 0 <= int(bits) <= width:
            raise ValueError(s)
        size = 1 << (width - int(bits))
        lo = int(a) // size * size
        return a.version, lo, lo + size - 1
    a = address(s)
    return a.version, int(a), int(a)


def ip_text(n, version):
    return str(ipaddress.IPv4Address(n) if version == 4 else ipaddress.IPv6Address(n))


def format_ip_range(lo, hi, version, cidr=True):
    a = ip_text(lo, version)
    if lo == hi:
        return a
    size = hi - lo + 1
    if cidr and size & (size - 1) == 0 and lo % size == 0:
        return a + '/' + str((32 if version == 4 else 128) - (size.bit_length() - 1))
    return a + '-' + ip_text(hi, version)


class PortError(ValueError):
    def __init__(self, character=None):
        self.character = character


def ports(s, offset=0):
    result = []
    pos = 0
    length = len(s)
    def number(p):
        m = re.match(r'(?:0[xX][0-9a-fA-F]+|0[0-7]*|[1-9][0-9]*)', s[p:])
        if not m:
            return 0, p
        st = m.group()
        v = int(st, 16) if st.lower().startswith('0x') else int(st, 8) if st.startswith('0') else int(st)
        return v, p + len(st)
    while pos < length:
        while pos < length and s[pos].isspace():
            pos += 1
        if pos + 1 < length and s[pos + 1] == ':':
            letter = s[pos].upper()
            if letter not in 'TUSIO':
                raise PortError(s[pos])
            offset = {'T': 0, 'U': 65536, 'S': 131072, 'I': 196608, 'O': 196864}[letter]
            pos += 2
        while pos < length and s[pos].isspace():
            pos += 1
        if pos >= length or (not s[pos].isdigit() and s[pos] != '-'):
            break
        if s[pos] == '-':
            lo = 1
        else:
            lo, pos = number(pos)
        while pos < length and s[pos].isspace():
            pos += 1
        hi = lo
        if pos < length and s[pos] == '-':
            pos += 1
            while pos < length and s[pos].isspace():
                pos += 1
            if pos < length and s[pos].isdigit():
                hi, pos = number(pos)
            else:
                hi = 65535
        if lo > 65535 or hi > 65535 or hi < lo:
            raise PortError()
        result.append((lo + offset, hi + offset))
        while pos < length and s[pos].isspace():
            pos += 1
        if pos < length and s[pos] == ',':
            pos += 1
        else:
            break
    return merge(result)


def format_ports(items):
    result = []
    for lo, hi in merge(items):
        off = min(lo // 65536, 3) * 65536
        prefix = {0: '', 65536: 'U:', 131072: 'S:', 196608: 'I:'}[off]
        text = prefix + str(lo - off)
        if hi != lo:
            text += '-' + str(hi - off)
        result.append(text)
    return ','.join(result)


def count(items):
    return sum(b - a + 1 for a, b in items)


def pick(items, index):
    for lo, hi in items:
        size = hi - lo + 1
        if index < size:
            return lo + index
        index -= size
    raise IndexError(index)
