    def select(self):
        if self.mode is None:
            self.mode = 'scan'

    def add_ranges(self, s, exclude=False):
        target = self.ex if exclude else self.ip
        text = re.sub(r'\s*([/-])\s*', r'\1', s)
        tokens = re.split(r'[,\s]+', text.strip())
        for token in tokens:
            if not token:
                continue
            try:
                version, lo, hi = rg.ip_range(token)
                if hi >= lo:
                    target[version].append((lo, hi))
            except ValueError:
                err('ERROR: bad IP address/range: ' + s + '\n')
