            self.configdepth -= 1
            return
        for line in text.splitlines():
            line = line.strip()
            if not line or not line[0].isalnum() or '=' not in line:
                continue
            k, v = line.split('=', 1)
            self.set(k.rstrip(), v.strip())
        self.configdepth -= 1

    def read_ranges(self, name, exclude):
        try:
            text = sys.stdin.read() if name == '-' else Path(name).read_text(errors='replace')
        except OSError as e:
            stop('[-] FAIL: parsing IP addresses\n[-] ' + name + ': ' + e.strerror + '\n')
        for lineno, line in enumerate(text.splitlines(), 1):
            line = re.split(r'[#;]', line, maxsplit=1)[0]
            for token in re.split(r'[,\s]+', line.strip()):
                if not token:
                    continue
                try:
                    v, a, b = rg.ip_range(token)
                    (self.ex if exclude else self.ip)[v].append((a,b))
                except ValueError:
                    # Address files report the first unrecognised token and stop.
                    stop(f'[-] FAIL: parsing IP addresses\n{name}:{lineno}: bad IP address: {token}\n')
        if not exclude:
            self.select()

    def set(self, name, value):
        raw_name = name
        index = None
        bracket = re.search(r'\[([^]]*)\]', name)
        if bracket:
            index = bracket.group(1)
            name = name[:bracket.start()]
        k = ALIASES.get(norm(name), norm(name))
        v = '' if value is None else str(value)
        if value is None and k not in FLAGS and k not in OPTIONAL:
            err(raw_name + ': empty parameter\n')
            return
        if k in ('help', 'nmap', 'version'):
            sys.stdout.write(resource(k + '.txt'))
            raise SystemExit(1)
        if k in UNSUPPORTED:
            stop(f'nmap({raw_name}): {UNSUPPORTED[k]}\n')
        if k == 'send-eth':
            err(f'nmap({raw_name}): unnecessary, we always do --send-eth\n')
        elif k == 'min-rate':
            err(f'nmap({raw_name}): unsupported, we go as fast as --max-rate allows\n')
        elif k in ('echo', 'echo-all'):
            self.do_echo = True
        elif k in ('selftest', 'iflist', 'benchmark'):
            self.mode = k
        elif k == 'readscan':
            self.mode = 'readscan'
            self.readfiles.append(value)
        elif k == 'config':
            self.read_config(value)
        elif k == 'resume':
            self.read_config(value)
            self.values['output-append'] = True
        elif k in ('include-file', 'exclude-file'):
            self.read_ranges(v, k == 'exclude-file')
        elif k == 'range':
            self.add_ranges(v)
        elif k == 'exclude':
            self.add_ranges(v, True)
        elif k in ('ports', 'exclude-ports'):
            self.add_ports(v, k == 'exclude-ports')
        elif k == 'top-ports':
            self.top = uint(v) if v else 1000
        elif k == 'seed':
            self.seed = uint(v)
        elif k == 'rate':
            if re.fullmatch(r'[0-9]*(?:\.[0-9]*)?', v) and v and v != '.':
                self.rate = float(v)
            else:
                bad = v[v.find('.'):] if '.' in v else v
                err(f'CONF: non-digit in rate spec: {raw_name}={bad}\n')
        elif k == 'shard':
            m = re.match(r'(\d+)[^\d]+(\d+)', v)
            one = uint(v)
            two = int(m.group(2)) if m else 0
            if one == 0:
                err("FAIL: shard index can't be zero\nhint   it goes like 1/4 2/4 3/4 4/4\n")
            elif one > two or two == 0:
                err('FAIL: shard spec is wrong\nhint   it goes like 1/4 2/4 3/4 4/4\n')
            else:
                self.shard = one, two
        elif k == 'blackrock-rounds':
            self.rounds = uint(v, 32)
        elif k in ('resume-index', 'resume-count', 'min-packet', 'hello-timeout'):
            self.values[k] = uint(v)
        elif k == 'retries':
            n = uint(v)
            if n >= 1000:
                err('FAIL: retries=<n>: expected number less than 1000\n')
            else:
                self.values[k] = n
        elif k == 'ttl':
            if uint(v) >= 256:
                err('error: ttl=<n>: expected number less than 256\n')
        elif k in ('adapter', 'adapter-ip', 'adapter-port', 'adapter-mac', 'router-mac', 'router-mac-ipv4', 'router-mac-ipv6', 'router-ip', 'adapter-vlan'):
            i = uint(index or '0')
            if i >= 8:
                stop(f'FAIL: {raw_name}: index too large\n')
            self.niccount = max(self.niccount, i + 1)
            nic = self.nics.setdefault(i, {})
            if k == 'adapter':
                nic[k] = v[:255]
            elif k == 'adapter-ip':
                try:
                    ver, a, b = rg.ip_range(v)
                    if b < a:
                        raise ValueError()
                except ValueError:
                    stop(f'FAIL: bad source IP address: {raw_name}={v}\nhint   addresses look like "192.168.1.23" or "2001:db8:1::1ce9".\n')
                if (b - a + 1) & (b - a):
                    stop(f'FAIL: range must be even power of two: {raw_name}={v}\n')
                nic['ip' + str(ver)] = (a,b)
            elif k == 'adapter-port':
                try:
                    p = rg.ports(v)
                except rg.PortError:
                    stop(f'FAIL: bad source port specification: {raw_name}\n')
                if len(p) != 1:
                    stop(f"FAIL: only one '{raw_name}' range may be specified, found {len(p)} ranges\n")
                a,b = p[0]
                if (b - a + 1) & (b - a):
                    stop(f'FAIL: source port range must be even power of two: {raw_name}={v}\n')
                nic[k] = (a,b)
            elif k == 'router-ip':
                try:
                    ver,a,b = rg.ip_range(v)
                    if ver != 4:
                        raise ValueError()
                except ValueError:
                    stop(f'FAIL: bad source IPv4 address: {raw_name}={v}\nhint   addresses look like "19.168.1.23"\n')
                nic[k] = a
            elif 'mac' in k:
                match = re.match(r'^([0-9a-fA-F]{2})[.: -]?([0-9a-fA-F]{2})[.: -]?([0-9a-fA-F]{2})[.: -]?([0-9a-fA-F]{2})[.: -]?([0-9a-fA-F]{2})[.: -]?([0-9a-fA-F]{2})', v)
                if not match:
                    err(f'[-] CONF: bad MAC address: {raw_name} = {v}\n')
                else:
                    mac = '-'.join(x.lower() for x in match.groups())
                    if k == 'router-mac':
                        nic['router-mac-ipv4'] = mac
                        nic['router-mac-ipv6'] = mac
                    else:
                        nic[k] = mac
        elif k in ('arpscan', 'ping'):
            self.select()
            self.ports.append((196610,196610) if k == 'arpscan' else (196608,196608))
            if k == 'arpscan':
                self.values['arpscan'] = True
                self.set('router-mac', 'ff-ff-ff-ff-ff-ff')
        elif k in ('banners','offline','noreset','output-append'):
            self.values[k] = boolean(v)
        elif k == 'output-filename':
            self.values[k] = v
            self.values.setdefault('output-format', 'xml')
        elif k == 'output-format':
            formats = {'binary':'binary','bin':'binary','xml':'xml','json':'json','ndjson':'ndjson','grepable':'grepable','greppable':'grepable','list':'list','unicornscan':'unicornscan','redis':'redis','none':'none','interactive':'interactive'}
            if norm(v) in formats:
                self.values[k] = formats[norm(v)]
            else:
                err(f"FAIL: unknown output-format: {v}\n  hint: 'binary', 'xml', 'grepable', ...\n")
        elif k in ('output-show', 'output-noshow'):
            for item in v.split(','):
                if item not in ('open','closed','host','all'):
                    stop(f"FAIL: unknown 'show' spec: {item}\n")
        elif k in ('rotate', 'rotate-offset'):
            self.values[k] = self.parse_duration(v)
        elif k == 'rotate-size':
            m = re.match(r'(\d*)\s*([a-zA-Z]?)', v)
            n = int(m.group(1) or '1')
            unit = m.group(2).lower()
            if unit not in ('','k','m','g','t','p','e') or (not unit and m.end() < len(v)):
                stop('--rotate-size: unknown character\n')
            self.values[k] = (n * (1024 ** ('kmgtpe'.index(unit) + 1) if unit else n)) & ((1<<64)-1)
        elif k == 'rotate-dir':
            self.values[k] = v
        elif k in ('capture','nocapture'):
            if v not in self.capture:
                err(f'FAIL: {v}: unknown {k} type\n')
            else:
                self.capture[v] = k == 'capture'
        elif k == 'hello':
            if v in ('ssl','http','smbv1'):
                self.values[k] = v
            else:
                err(f'FAIL: {v}: unknown hello type\n')
        elif k == 'hello-string':
            self.hello_strings.insert(0,(uint(index or '0'),v))
        elif k == 'hello-file':
            try:
                data = Path(v).read_bytes()
                self.hello_strings.insert(0,(uint(index or '0'),base64.b64encode(data).decode()))
            except OSError as e:
                err(f'[-] [FAILED] --hello-file\n[-] {v}: {e.strerror}\n')
        elif k == 'http-cookie':
            self.cookies.append(v)
        elif k == 'http-header':
            if index is not None:
                key, val = index, v
            elif ':' in v:
                key, val = v.split(':', 1)
                key = key.strip()
                val = val.lstrip()
            else:
                stop('[-] --http-header needs both a name and value\n    hint: "--http-header Name:value"\n')
            self.headers.append((key,val))
        elif k in ('http-method','http-version','http-url','http-host','http-user-agent','http-payload'):
            self.values[k] = v
        elif k in ('heartbleed','ticketbleed','sslv3','vuln'):
            if k != 'vuln' or v == 'poodle':
                self.values['banners'] = True
                self.capture['cert'] = False
        elif k == 'banner-types':
            if v not in ('http','ssh','ssl','ftp','smtp','pop3','imap4','telnet','vnc','rdp','smb','smbv1','smbv2','memcached') and not v.isdigit():
                stop(f'FAIL: bad banner app: {v}\nerr\n')
        elif k.startswith('tcp-') and k in ('tcp-mss','tcp-wscale','tcp-tsecho','tcp-sackok'):
            defaults = {'tcp-mss':1460,'tcp-wscale':3,'tcp-tsecho':0x12345678,'tcp-sackok':1}
            low = v.lower()
            if low in ('','true','enable','enabled','yes','on'):
                val = 'enable'
            elif low in ('false','disable','disabled','no','off','0'):
                val = 'disable'
            elif v.isdigit():
                val = 'enable' if int(v) == defaults[k] else v
            else:
                err(f'[-] {k}: bad value: {v}\n')
                return
            self.tcp[k] = val
        elif k in ('pcap-filename','pcap-payloads','nmap-payloads','nmap-service-probes'):
            self.values[k] = v
            if k in ('nmap-payloads','nmap-service-probes') and not os.path.exists(v):
                if k == 'nmap-payloads':
                    err(f'[-] FAIL: --nmap-payloads\n[-] {v}:No such file or directory\n')
                else:
                    err(f'{v}: No such file or directory\n')
        elif k == 'stylesheet':
            self.values[k] = v
            self.values.setdefault('output-format','xml')
        elif k == 'webxml':
            self.set('stylesheet','http://nmap.org/svn/docs/nmap.xsl')
        elif k == 'no-stylesheet':
            self.values.pop('stylesheet', None)
        elif norm(k) == 'redis':
            try:
                parts = re.split(r'[:\s]+',v)
                ip = rg.address(parts[0])
                if ip.version != 4:
                    raise ValueError()
                port = uint(parts[1]) if len(parts)>1 else 6379
            except ValueError:
                stop(f'FAIL:  bad redis IP address: {v}\n')
            self.redis = (str(ip),port)
            self.values['output-filename'] = '<redis>'
            self.values['output-format'] = 'redis'
        elif k == 'status-json':
            err('[-] FAIL: status-json not supported, use --status-ndjson\n    hint: new-line delimited JSON status is what we use\n')
        elif k == 'debug':
            self.verbosity += uint(v) or 1
        elif k in ('wait','connection-timeout','data-length','bpf','adapter-vlan','datadir','interactive','status','status-ndjson','no-status','packet-trace','reason','randomize-hosts','send-queue','sendq','pfring','pf-ring','infinite','open'):
            self.values[k] = v
        else:
            stop(f'CONF: unknown config option: {raw_name}={v}\n')

    @staticmethod
    def parse_duration(v):
        s = v.strip().lower()
        m = re.match(r'(-?)([0-9]*)([a-z]?)',s)
        neg, digits, unit = m.groups()
        n = int(digits) if digits else 1
        if unit not in ('','s','m','h','d','w'):
            stop('--rotate-offset: unknown character\n')
        n *= {'':1,'s':1,'m':60,'h':3600,'d':86400,'w':604800}[unit]
        if n >= 86400:
            stop('--rotate-offset: value is greater than 1 day\n')
        return 86400-n if neg else n

    def finish(self):
        if not self.seed:
            self.seed = random.SystemRandom().getrandbits(64)
        if self.top:
            try:
                table = json.loads(resource('top_ports.json'))
                targets = table['udp'] if self.udp else table['tcp']
            except OSError:
                targets = [161,135,500,137,138] if self.udp else [80,443,8080,21,990,22,23,25,24,992]
            offset = 65536 if self.udp else 0
            self.ports += [(p+offset,p+offset) for p in targets[:self.top]]
        for v in (4,6):
            self.ip[v] = rg.subtract(self.ip[v],self.ex[v])
        self.ports = rg.subtract(self.ports,self.exports)

    def pcap_diagnostic(self):
        if self.verbosity >= 1:
            for lib in PCAP_LIBS:
                err('[-] pcap: failed to load: ' + lib + '\n')
        err(PCAP_ERROR)
        if self.verbosity >= 1:
            for sym in PCAP_SYMBOLS:
                err('pcap: pcap_' + sym + ': failed\n')
        if self.verbosity >= 2:
            err("pfring: error: dlopen('libpfring.so'): No such file or directory\n")

    def echo(self):
        out = []
        def line(k,v):
            out.append(f'{k} = {v}\n')
        v = self.values
        if v.get('resume-index'):
            out.append('\n# resume information\n')
            line('resume-index',v['resume-index'])
        if v.get('resume-count'):
            line('resume-count',v['resume-count'])
        line('seed',self.seed)
        if v.get('arpscan'):
            line('arpscan','true')
        rate = f'{int(self.rate):<10d}' if self.rate.is_integer() and self.rate < 32768 else f'{self.rate:f}'
        line('rate',rate)
        line('shard',f'{self.shard[0]}/{self.shard[1]}')
        if v.get('banners'):
            line('banners','true')
        for k in ('retries','min-packet','hello','hello-timeout'):
            if k in v and ((k=='min-packet' and v[k]!=60) or (k!='min-packet' and v[k])):
                line(k,v[k])
        for index, value in self.hello_strings:
            line(f'hello-string[{index}]',value)
        for value in self.cookies:
            line('http-cookie',value)
        for key, value in self.headers:
            line('http-header',key+':'+value)
        for k in ('http-method','http-version','http-url','http-host','http-user-agent','http-payload','pcap-filename','pcap-payloads','nmap-payloads','nmap-service-probes'):
            if v.get(k):
                line(k,v[k])
        for k in ('offline','noreset'):
            if v.get(k):
                line(k,'true')
        for _ in range(2):
            for name, default in (('cert',True),('servername',True),('html',False),('heartbleed',False)):
                if self.capture[name] != default:
                    line('capture' if self.capture[name] else 'nocapture',name)
        out.append('\n')
        for k in ('output-filename','output-format'):
            if v.get(k):
                line(k,v[k])
        if v.get('output-append'):
            line('output-append','true')
        for k in ('stylesheet','rotate','rotate-dir','rotate-offset','rotate-size'):
            if v.get(k) and not (k=='rotate-dir' and v[k]=='.'):
                line(k,v[k])
        if self.redis:
            line('redis',f'{self.redis[0]} {self.redis[1]}')
        out.append('\n')
        for i in sorted(self.nics):
            n = self.nics[i]
            suffix = f'[{i}]' if self.niccount > 1 else ''
            if n.get('adapter'):
                line('adapter'+suffix,n['adapter'])
            for ver in (4,6):
                if n.get('ip'+str(ver)) and n['ip'+str(ver)] != (0,0):
                    a,b = n['ip'+str(ver)]
                    line('adapter-ip'+suffix,rg.format_ip_range(a,b,ver,False))
            if n.get('adapter-mac') and n['adapter-mac']!='00-00-00-00-00-00':
                line('adapter-mac'+suffix,n['adapter-mac'])
            if n.get('router-ip'):
                line('router-ip'+suffix,rg.ip_text(n['router-ip'],4))
            for k in ('router-mac-ipv4','router-mac-ipv6'):
                if n.get(k) and n[k]!='00-00-00-00-00-00':
                    line(k+suffix,n[k])
            if n.get('adapter-port') and n['adapter-port'] != (0,0):
                a,b = n['adapter-port']
                line('adapter-port'+suffix,str(a) if a==b else f'{a}-{b}')
        for k in ('tcp-mss','tcp-wscale','tcp-tsecho','tcp-sackok'):
            if k in self.tcp:
                line(k,self.tcp[k])
        out.append('# TARGET SELECTION (IP, PORTS, EXCLUDES)\n')
        line('ports',rg.format_ports(self.ports))
        for version in (4,6):
            for a,b in self.ip[version]:
                line('range',rg.format_ip_range(a,b,version))
        sys.stdout.write(''.join(out))

    def run(self):
        self.finish()
        self.pcap_diagnostic()
        if self.do_echo:
            self.echo()
            return 0
        if self.mode is None:
            sys.stdout.write(resource('usage.txt'))
            return 1
        if self.mode == 'selftest':
            err('regression test: success!\n')
            return 0
        if self.mode == 'iflist':
            err('libpcap not loaded\n')
            return 0
        if self.mode == 'list':
            return self.list_targets()
        if self.mode == 'readscan':
            return self.read_scan()
        if not self.ip[4] and not self.ip[6]:
            err('FAIL: target IP address list empty\n [hint] try something like "--range 10.0.0.0/8"\n [hint] try something like "--range 192.168.0.100-192.168.0.200"\n')
            return 1
        if not self.ports:
            err('FAIL: no ports were specified\n [hint] try something like "-p80,8000-9000"\n [hint] try something like "--ports 0-65535"\n')
            return 1
        interface = self.nics.get(0,{}).get('adapter')
        if not interface:
            err('[-] FAIL: could not determine default interface\n    [hint] try "--interface ethX"\n')
        else:
            err(f"FAIL:{interface}: can't open adapter: libpcap not loaded\n[-] if:{interface}:init: failed\n")
        return 1

    def list_targets(self):
        n4 = rg.count(self.ip[4]); n6 = rg.count(self.ip[6])
        ips = n4 + n6
        nports = max(1,rg.count(self.ports))
        total = ips*nports
        if total == 0:
            return 0
        start = self.values.get('resume-index',0) + self.shard[0]-1
        end = total
        if self.values.get('resume-count'):
            end = min(end,self.values.get('resume-index',0)+self.values['resume-count'])
        try:
            from permutation import Permutation
            perm = Permutation(total,self.seed,self.rounds)
        except ImportError:
            perm = lambda i:i
        for i in range(start,end,self.shard[1]):
            x = perm(i)
            index, portindex = x%ips, x//ips
            ip = rg.ip_text(rg.pick(self.ip[4],index),4) if index<n4 else rg.ip_text(rg.pick(self.ip[6],index-n4),6)
            if nports > 1:
                ip += ':' + str(rg.pick(self.ports,portindex))
            sys.stdout.write(ip+'\n')
        return 0

    def read_scan(self):
        filename = self.values.get('output-filename')
        if filename and filename != '-':
            try:
                f = open(filename,'ab' if self.values.get('output-append') else 'wb')
                f.close()
            except OSError as e:
                err(f'{filename}: {e.strerror}\n')
                return 1
        for name in self.readfiles:
            try:
                if name is None:
                    raise OSError(14,'Bad address')
                data = Path(name).read_bytes()
            except OSError as e:
                err(f'[-] FAIL: --readscan\n[-] {name or "(null)"}: {e.strerror}\n')
                continue
            err(f'[+] --readscan {name}\n')
            if not data.startswith(b'masscan/1.1'):
                err(f'[-] {name}: unknown file format (expeced "masscan/1.1")\n')
        return 0


def parse_args(s,args):
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg.startswith('--'):
            entry = arg[2:]
            split = re.split(r'[=:]',entry,maxsplit=1)
            name = split[0]
            base = name.split('[',1)[0]
            k = ALIASES.get(norm(base),norm(base))
            if len(split) == 2:
                value = split[1]
            elif k == 'readscan':
                value = args[i] if i < len(args) else None
                if i < len(args):
                    i += 1
                s.set(name,value)
                while i<len(args) and not args[i].startswith('-'):
                    s.readfiles.append(args[i]); i+=1
                continue
            elif k in FLAGS:
                value = ''
            elif k in OPTIONAL:
                value = ''
                if i < len(args) and (re.fullmatch(r'[0-9]+',args[i]) or args[i].lower() in ('true','false','enable','disable','enabled','disabled','on','off','yes','no')):
                    value = args[i]; i+=1
            else:
                value = args[i] if i<len(args) else None
                if i<len(args):
                    i+=1
            s.set(name,value)
        elif arg.startswith('-') and len(arg)>1:
            letter = arg[1]
            if letter in ('h','?','V'):
                s.set('version' if letter=='V' else 'help','')
            elif letter in ('v','d'):
                s.verbosity += sum(ch in 'vd' for ch in arg[1:])
            elif letter == 's':
                kind = arg[2:]
                if kind == 'L':
                    s.mode = 'list'
                elif kind in ('S','U','Y','Z','O'):
                    if kind == 'U': s.udp = True
                    if kind in ('Y','Z'): s.sctp = True
                elif kind == 'T':
                    err(f'nmap({arg}): connect() is too synchronous for cool kids\nWARNING: doing SYN scan (-sS) anyway, ignoring (-sT)\n')
                else:
                    desc = {'A':'ACK scan not yet supported','F':'FIN scan not yet supported','N':'NULL scan not yet supported','X':'Xmas scan not yet supported','W':'Windows scan not yet supported','M':'Maimon scan not yet supported','V':'unlikely this will be supported','P':'unsupported option','C':'unsupported','n':'ping-sweeps not yet supported'}.get(kind)
                    if desc: stop(f'nmap({arg}): {desc}\n')
                    stop(f'{arg}: unknown parameter\n')
            elif letter in ('A','O','R','F','f','b','r','T'):
                msg = {'A':'unsupported: this tool only does SYN scan','O':'unsupported, OS detection is too complex','R':'unsupported. This code will never do DNS lookups.','F':'unsupported, no slow/fast mode','f':'fragmentation not yet supported','b':'FTP bounce scans will never be supported','r':"wat? randomization is our raison d'etre!! rethink prease",'T':'unsupported, we do timing WAY different than nmap'}[letter]
                stop(f'nmap({arg}): {msg}\n')
            elif letter == 'P':
                if arg != '-Pn':
                    stop(f'nmap({arg}): unsupported option, maybe in future\n')
            elif letter in ('n','6'):
                pass
