        elif arg and (arg[0].isdigit() or ':' in arg):
            s.add_ranges(arg)
        else:
            stop(f'FAIL: unknown command-line parameter "{arg}"\n [hint] did you want "--{arg}"?\n')


def main():
    s = Settings()
    default = '/etc/masscan/masscan.conf'
    if os.path.isfile(default):
        s.read_config(default)
    parse_args(s,sys.argv[1:])
    return s.run()


