    def select(self):
        if self.mode is None:
            self.mode = 'scan'

    def add_ranges(self, s, exclude=False):
        target = self.ex if exclude else self.ip
        text = re.sub(r'\s*([/-])\s*', r'\1', s)
        tokens = re.split(r'[,\s]+', text.strip())
        for token in tokens:
            if not token:
                continue
            try:
                version, lo, hi = rg.ip_range(token)
                if hi >= lo:
                    target[version].append((lo, hi))
            except ValueError:
                err('ERROR: bad IP address/range: ' + s + '\n')
                break
        if not exclude:
            self.select()

    def add_ports(self, s, exclude=False):
        try:
            items = rg.ports(s, 65536 if self.udp and not exclude else 0)
        except rg.PortError as e:
            if e.character:
                err('bad port character = ' + e.character + '\n')
            stop('[-] FAIL: bad target port: ' + s + '\n    Hint: a port is a number [0..65535]\n')
        if exclude:
            self.exports += items
        else:
            self.ports += items
            self.select()

    def read_config(self, name):
