        except OSError as e:
            err('[-] FAIL: reading configuration file\n[-] ' + (name or '(null)') + ': ' + e.strerror + '\n[-] cwd = ' + os.getcwd() + '\n')
            return
        self.configdepth += 1
        if self.configdepth > 20:
            self.configdepth -= 1
            return
        for line in text.splitlines():
            line = line.strip()
            if not line or not line[0].isalnum() or '=' not in line:
                continue
            k, v = line.split('=', 1)
            self.set(k.rstrip(), v.strip())
        self.configdepth -= 1

    def read_ranges(self, name, exclude):
        try:
            text = sys.stdin.read() if name == '-' else Path(name).read_text(errors='replace')
