"""Decode compact scan records and serialize the supported report formats."""
import os
from pathlib import Path
import socket
import struct
import sys
import time
import ranges as rg

APPLICATIONS = ('unknown unknown ssh ssh http ftp dns-ver snmp nbtstat ssl smb smtp pop imap zeroaccess X509 X509CA title html ntp vuln heartbleed ticketbleed vnc safe memcached scripting versioning coap telnet rdp http.server minecraft vnc vnc-info isakmp error').split()


def appname(n):
    return APPLICATIONS[n] if n < len(APPLICATIONS) else f'({n})'


def protocol(n):
    return {6:'tcp',17:'udp',132:'sctp',1:'icmp',47:'gre'}.get(n,str(n))


def reason(n):
    return '-'.join(name for i,name in enumerate(('fin','syn','rst','psh','ack','urg','ece','cwr')) if n & (1<<i)) or 'none'


