    prefix = '\\u00' if json_format else '\\x'
    return ''.join(chr(x) if 32<=x<=126 and x not in (34,39,60,62,38,92) else prefix+f'{x:02x}' for x in data)


def service(port,proto):
    try:
        return socket.getservbyport(port,proto)
    except (OSError,OverflowError):
        return 'unknown'


def varint(n):
    result = [n&127]
    n >>= 7
    while n:
        result.append((n&127)|128); n>>=7
    return bytes(reversed(result))


