        if kind == 3 and len(data)>=12:
            timestamp,ip,port,app=struct.unpack('!IIHH',data[:12]); proto=6;ttl=0;payload=data[12:]
        elif kind == 5 and len(data)>=13:
            timestamp,ip,proto,port,app=struct.unpack('!IIBHH',data[:13]);ttl=0;payload=data[13:]
        elif kind == 9 and len(data)>=14:
            timestamp,ip,proto,port,app,ttl=struct.unpack('!IIBHHB',data[:14]);payload=data[14:]
        else:
            return None
        return dict(time=timestamp,ip=ip,port=port,proto=proto,app=app,ttl=ttl,payload=payload,status='banner',version=4)
    return None


